package org.eclipse.rdf4j.repository.sparql.federation;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.DynamicContainer.dynamicContainer;
import static org.junit.jupiter.api.DynamicTest.dynamicTest;

import java.util.ArrayList;
import java.util.List;
import java.util.stream.Stream;

import org.eclipse.rdf4j.common.iteration.CloseableIteration;
import org.eclipse.rdf4j.common.iteration.Iterations;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.impl.ListBindingSet;
import org.eclipse.rdf4j.query.impl.MapBindingSet;
import org.eclipse.rdf4j.repository.sparql.query.InsertBindingSetCursor;
import org.eclipse.rdf4j.repository.sparql.query.SPARQLQueryBindingSet;
import org.junit.jupiter.api.DynamicContainer;
import org.junit.jupiter.api.TestFactory;

class FederationBindingMergeTest {

	private enum Adapter {
		ROW_INDEX_JOIN,
		CROSS_PRODUCT,
		SINGLE_INPUT
	}

	@TestFactory
	Stream<DynamicContainer> bindingMerges() {
		return Stream.of(Adapter.values())
				.map(adapter -> dynamicContainer(adapter.name(), List.of(
						dynamicTest("compatible shared bindings", () -> compatibleSharedBindingsAreMergedOnce(adapter)),
						dynamicTest("conflicting rows",
								() -> conflictingRowsAreExcludedWithoutStoppingIteration(adapter)),
						dynamicTest("binding representations",
								() -> bindingSetRepresentationDoesNotChangeCompatibility(adapter)),
						dynamicTest("unbound input", () -> unboundInputSlotIsFilledByRemoteValue(adapter)),
						dynamicTest("unbound remote", () -> unboundRemoteSlotDoesNotOverwriteInputValue(adapter)),
						dynamicTest("unbound slots", () -> unboundSlotsRemainAbsent(adapter)),
						dynamicTest("duplicate remote rows", () -> duplicateRemoteRowsPreserveMultiplicity(adapter)),
						dynamicTest("exhaustion closes source", () -> exhaustingFilteredResultsClosesSource(adapter)),
						dynamicTest("early close closes source", () -> earlyCloseClosesSourceOnce(adapter)))));
	}

	void compatibleSharedBindingsAreMergedOnce(Adapter adapter) {
		BindingSet input = bindings("shared", "a", "left", "l");
		BindingSet remote = bindings("shared", "a", "right", "r");

		assertEquals(List.of(bindings("shared", "a", "left", "l", "right", "r")),
				merge(adapter, input, List.of(remote)));
	}

	void conflictingRowsAreExcludedWithoutStoppingIteration(Adapter adapter) {
		BindingSet input = bindings("shared", "a", "left", "l");
		BindingSet conflict = bindings("shared", "b", "right", "conflict");
		BindingSet compatible = bindings("shared", "a", "right", "r");

		assertEquals(List.of(bindings("shared", "a", "left", "l", "right", "r")),
				merge(adapter, input, List.of(conflict, compatible)));
	}

	void bindingSetRepresentationDoesNotChangeCompatibility(Adapter adapter) {
		BindingSet input = new SPARQLQueryBindingSet(bindings("shared", "a"));
		BindingSet remote = new SPARQLQueryBindingSet(bindings("shared", "b"));

		assertEquals(List.of(), merge(adapter, input, List.of(remote)));
	}

	void unboundInputSlotIsFilledByRemoteValue(Adapter adapter) {
		BindingSet input = new ListBindingSet(List.of("shared", "left"), null, value("l"));
		BindingSet remote = bindings("shared", "a", "right", "r");

		assertEquals(List.of(bindings("shared", "a", "left", "l", "right", "r")),
				merge(adapter, input, List.of(remote)));
	}

	void unboundRemoteSlotDoesNotOverwriteInputValue(Adapter adapter) {
		BindingSet input = bindings("shared", "a", "left", "l");
		BindingSet remote = new ListBindingSet(List.of("shared", "right"), null, value("r"));

		assertEquals(List.of(bindings("shared", "a", "left", "l", "right", "r")),
				merge(adapter, input, List.of(remote)));
	}

	void unboundSlotsRemainAbsent(Adapter adapter) {
		BindingSet input = new ListBindingSet(List.of("shared", "left"), null, value("l"));
		BindingSet remote = new ListBindingSet(List.of("shared", "right"), null, value("r"));

		List<BindingSet> result = merge(adapter, input, List.of(remote));
		assertEquals(List.of(bindings("left", "l", "right", "r")), result);
		assertFalse(result.get(0).hasBinding("shared"));
	}

	void duplicateRemoteRowsPreserveMultiplicity(Adapter adapter) {
		BindingSet input = bindings("shared", "a", "left", "l");
		BindingSet remote = bindings("shared", "a", "right", "r");
		BindingSet expected = bindings("shared", "a", "left", "l", "right", "r");

		assertEquals(List.of(expected, expected), merge(adapter, input, List.of(remote, remote)));
	}

	void exhaustingFilteredResultsClosesSource(Adapter adapter) {
		TrackingIteration source = source(adapter, List.of(bindings("shared", "b")));
		try (CloseableIteration<BindingSet> result = create(adapter, source, bindings("shared", "a"))) {
			assertFalse(result.hasNext());
			assertEquals(1, source.closeCount);
		}
		assertEquals(1, source.closeCount);
	}

	void earlyCloseClosesSourceOnce(Adapter adapter) {
		TrackingIteration source = source(adapter, List.of(bindings("remote", "r")));
		CloseableIteration<BindingSet> result = create(adapter, source, bindings("left", "l"));
		result.close();
		result.close();
		assertEquals(1, source.closeCount);
	}

	private static List<BindingSet> merge(Adapter adapter, BindingSet input, List<BindingSet> remote) {
		try (CloseableIteration<BindingSet> result = create(adapter, source(adapter, remote), input)) {
			return Iterations.asList(result);
		}
	}

	private static CloseableIteration<BindingSet> create(Adapter adapter, CloseableIteration<BindingSet> source,
			BindingSet input) {
		switch (adapter) {
		case ROW_INDEX_JOIN:
			return new ServiceJoinConversionIteration(source, List.of(input));
		case CROSS_PRODUCT:
			return new SPARQLCrossProductIteration(source, List.of(input));
		case SINGLE_INPUT:
			return new InsertBindingSetCursor(source, input);
		default:
			throw new AssertionError(adapter);
		}
	}

	private static TrackingIteration source(Adapter adapter, List<BindingSet> rows) {
		if (adapter != Adapter.ROW_INDEX_JOIN) {
			return new TrackingIteration(rows);
		}
		List<BindingSet> indexedRows = new ArrayList<>();
		for (BindingSet row : rows) {
			List<String> names = new ArrayList<>(row.getBindingNames());
			List<Value> values = new ArrayList<>();
			for (String name : names) {
				values.add(row.getValue(name));
			}
			names.add("__rowIdx");
			values.add(value("0"));
			indexedRows.add(new ListBindingSet(names, values));
		}
		return new TrackingIteration(indexedRows);
	}

	private static MapBindingSet bindings(String... pairs) {
		MapBindingSet result = new MapBindingSet(pairs.length / 2);
		for (int i = 0; i < pairs.length; i += 2) {
			result.addBinding(pairs[i], value(pairs[i + 1]));
		}
		return result;
	}

	private static Value value(String value) {
		return SimpleValueFactory.getInstance().createLiteral(value);
	}

	private static class TrackingIteration extends CollectionIteration<BindingSet> {
		private int closeCount;

		private TrackingIteration(List<BindingSet> rows) {
			super(rows);
		}

		@Override
		protected void handleClose() {
			closeCount++;
		}
	}
}
